export function translate(language: string, key: string) {
  if (key.startsWith('trip.')) return translations[language]?.[key] ?? additionalLanguageCopy[language]?.[key] ?? tripCopy[key] ?? key
  return translations[language]?.[key] ?? establishedLocaleCompletion[language]?.[key] ?? exploreLanguageCopy[language]?.[key] ?? additionalLanguageCopy[language]?.[key] ?? translations['en-IN']?.[key] ?? key
}
